function scoreSpread(weights: number[], k: number): number {
  const n = weights.length;
  let lo = Infinity, hi = -Infinity;
  const cuts: number[] = []; // a cut at g means a run ends at index g
  const score = () => {
    let s = 0, start = 0;
    for (const g of [...cuts, n - 1]) { s += weights[start] + weights[g]; start = g + 1; }
    return s;
  };
  const choose = (from: number) => {
    if (cuts.length === k - 1) { const s = score(); lo = Math.min(lo, s); hi = Math.max(hi, s); return; }
    for (let g = from; g <= n - 2; g++) { cuts.push(g); choose(g + 1); cuts.pop(); }
  };
  choose(0);
  return hi - lo;
}

