class Solution:
    def scoreSpread(self, weights: List[int], k: int) -> int:
        n = len(weights)
        scores = []
        for cuts in itertools.combinations(range(n - 1), k - 1):
            s, start = 0, 0
            for g in list(cuts) + [n - 1]:
                s += weights[start] + weights[g]
                start = g + 1
            scores.append(s)
        return max(scores) - min(scores)

