function scoreSpread(weights: number[], k: number): number {
  const pairs: number[] = [];
  for (let i = 0; i + 1 < weights.length; i++) pairs.push(weights[i] + weights[i + 1]);
  pairs.sort((a, b) => a - b);
  let diff = 0;
  for (let i = 0; i < k - 1; i++) diff += pairs[pairs.length - 1 - i] - pairs[i];
  return diff;
}

